  ObjectInputStream ois = new ObjectInputStream(in);
  ois.setObjectInputFilter(ObjectInputFilter.Config.createFilter("com.x.*;!*"));
  return ois.readObject();
} }

class A { Object f(InputStream in) throws Exception {
  return new ObjectInputStream(in) {
    @Override protected Class<?> resolveClass(ObjectStreamClass d) throws IOException, ClassNotFoundException {
      if (!d.getName().startsWith("com.x.")) throw new InvalidClassException(d.getName());
      return super.resolveClass(d);
    }
  }.readObject();
} }

